<template>
  <main class="insights-page">
    <header class="hero">
      <div>
        <span class="eyebrow"><i class="eyebrow-dot" />PERSONAL INTELLIGENCE</span>
        <h1>我的兴趣情报</h1>
        <p>把分散在社区里的新鲜讨论，整理成一份只属于你的动态简报。</p>
      </div>
      <button class="primary" :disabled="loading || !enabledKeywords.length" @click="generate">
        <span v-if="loading" class="spinner" />{{ loading ? '正在整理…' : result ? '刷新情报' : '生成我的情报' }}
      </button>
    </header>

    <section class="keyword-card">
      <div class="section-title"><div><span class="section-kicker">YOUR SIGNALS</span><h2>关注关键词</h2><p>用几个词告诉我，你正在关心什么</p></div><span class="keyword-count"><b>{{ keywords.length }}</b><small>/ 30</small></span></div>
      <form class="keyword-form" @submit.prevent="addKeyword">
        <input v-model.trim="newKeyword" maxlength="80" placeholder="例如：人工智能、Spring Boot、演唱会" />
        <button type="submit" :disabled="!newKeyword || adding">{{ adding ? '添加中' : '添加关键词' }}</button>
      </form>
      <div v-if="keywords.length" class="chips"><button v-for="item in keywords" :key="item.id" type="button" class="chip" :class="{ off: !item.enabled }" @click="toggle(item)"><span>{{ item.keyword }}</span><small>{{ item.enabled ? '已启用' : '已停用' }}</small><b @click.stop="remove(item)">×</b></button></div>
      <div v-else class="hint">还没有关键词，先添加一个你想持续关注的主题。</div>
      <div v-if="keywords.length && !enabledKeywords.length" class="hint warning">请至少启用一个关键词，再生成你的情报。</div>
      <div v-if="result?.keywords?.length" class="used-keywords"><strong>本次使用：</strong>{{ result.keywords.join('、') }}</div>
    </section>

    <section class="result-head"><div><span class="eyebrow">LATEST BRIEFING</span><h2>为你发现</h2><p class="result-subtitle">来自已发布社区内容的精选信号 <span v-if="result">· 更新于 {{ formattedTime }}</span></p></div><div v-if="result" class="result-meta"><span class="metric"><b>{{ result.items?.length || 0 }}</b><small>条情报</small></span><span class="metric"><b>{{ result.matched_count || 0 }}</b><small>条相关内容</small></span></div></section>
    <div class="view-tabs"><button :class="{ active: view === 'all' }" @click="view = 'all'">全部情报</button><button :class="{ active: view === 'saved' }" @click="switchView('saved')">我的收藏 <em v-if="savedIds.length">{{ savedIds.length }}</em></button></div>
    <div v-if="error" class="notice error">{{ error }}</div>
    <div v-else-if="view === 'all' && !result && !loading" class="empty"><div class="empty-icon">✦</div><h3>准备好开始了吗？</h3><p>点击“生成我的情报”，从已发布的社区内容中找到真正与你相关的讨论。</p></div>
    <div v-else-if="loading" class="skeletons"><div v-for="i in 3" :key="i" class="skeleton" /></div>
    <div v-else-if="!displayItems.length" class="empty compact"><h3>{{ view === 'saved' ? '还没有收藏情报' : '暂时没有新的相关内容' }}</h3><p>{{ view === 'saved' ? '生成情报后，在卡片底部点击收藏，内容会保存在这里。' : '试试添加更具体的关键词，或稍后再来看看。' }}</p></div>
    <div v-else class="items"><article v-for="item in displayItems" :key="item.item_id" class="insight-card"><div class="card-top"><span class="confidence" :style="{ '--confidence': `${Math.round(item.confidence * 100)}%` }"><i />{{ Math.round(item.confidence * 100) }}% 匹配</span><button class="more" title="标记不感兴趣" @click="feedback(item, 'not_interested')">⋯</button></div><h3>{{ item.headline }}</h3><div class="target-keywords"><span>属于</span><b v-for="keyword in itemKeywords(item)" :key="keyword">{{ keyword }}</b></div><p class="summary">{{ item.summary }}</p><div class="evidence" v-for="evidence in item.evidence" :key="`${item.item_id}-${evidence.comment_id || evidence.post_id}`"><div class="evidence-mark">↳</div><div><p>{{ evidence.excerpt }}</p><small>{{ evidence.scene_name }} · {{ evidence.comment_id ? `评论 ${evidence.floor_no || ''} 楼` : '主帖' }} · 命中 {{ evidence.matched_keywords.join('、') }}</small><a v-if="evidence.url" :href="evidence.url" target="_blank" rel="noopener" @click="feedback(item, 'viewed')">查看原帖 →</a></div></div><div class="card-actions"><button :class="{ active: isSaved(item) }" @click="feedback(item, 'saved')">{{ isSaved(item) ? '★ 已收藏' : '☆ 收藏情报' }}</button><span v-if="feedbackState[item.item_id] === 'not_interested'" class="muted-action">已记录偏好，仍会在需要时再次推荐</span><span v-else>已绑定 {{ item.evidence.length }} 条原文证据</span></div></article></div>
  </main>
</template>

<script setup>
import { computed, getCurrentInstance, onMounted, ref } from 'vue'
const { proxy } = getCurrentInstance()
const keywords = ref([]); const newKeyword = ref(''); const result = ref(null); const loading = ref(false); const adding = ref(false); const error = ref(''); const generatedAt = ref(null); const feedbackState = ref({}); const savedIds = ref([]); const savedItems = ref([]); const view = ref('all'); let generationSequence = 0
// SQLite 返回的 enabled 是 0/1，不能用 `!== false`，否则 0 会被误当成启用。
const isKeywordEnabled = (item) => item.enabled === true || item.enabled === 1 || item.enabled === '1'
const enabledKeywords = computed(() => keywords.value.filter(isKeywordEnabled))
const displayItems = computed(() => view.value === 'saved' ? savedItems.value : (result.value?.items || []))
const isSaved = (item) => savedIds.value.includes(item.item_id)
const itemKeywords = (item) => item.target_keywords?.length
  ? item.target_keywords
  : [...new Set((item.evidence || []).flatMap((evidence) => evidence.matched_keywords || []))]
const formattedTime = computed(() => generatedAt.value ? new Date(generatedAt.value).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '')
const loadKeywords = async () => { const response = await proxy.Request({ url: proxy.Api.zentideInterestKeywords, method: 'GET', params: {}, showLoading: false }); if (response) keywords.value = response.data?.items || response.items || [] }
const addKeyword = async () => { if (!newKeyword.value) return; adding.value = true; const response = await proxy.Request({ url: proxy.Api.zentideInterestKeywords, params: { keyword: newKeyword.value }, dataType: 'json', showLoading: false }); adding.value = false; if (response) { newKeyword.value = ''; await loadKeywords() } }
const toggle = async (item) => { const response = await proxy.Request({ url: `${proxy.Api.zentideInterestKeywords}/${item.id}`, method: 'PATCH', params: { enabled: !item.enabled }, dataType: 'json', showLoading: false }); if (response) item.enabled = !item.enabled }
const remove = async (item) => { const response = await proxy.Request({ url: `${proxy.Api.zentideInterestKeywords}/${item.id}`, method: 'DELETE', params: {}, showLoading: false }); if (response) keywords.value = keywords.value.filter((entry) => entry.id !== item.id) }
const generate = async () => {
  if (!enabledKeywords.value.length || loading.value) return
  const sequence = ++generationSequence
  loading.value = true
  error.value = ''
  result.value = null
  const startedAt = Date.now()
  const responsePromise = proxy.Request({
    url: proxy.Api.zentideInterestInsights,
    params: {
      keywords: enabledKeywords.value.map((item) => item.keyword),
      maxItems: 10,
      seenPostIds: [],
    },
    dataType: 'json',
    showLoading: false,
    timeout: 30000,
  })
  const [response] = await Promise.all([responsePromise, new Promise((resolve) => setTimeout(resolve, Math.max(450 - (Date.now() - startedAt), 0)))])
  if (sequence !== generationSequence) return
  loading.value = false
  if (response) {
    result.value = response.data || response
    generatedAt.value = result.value.generated_at || new Date().toISOString()
  } else error.value = '情报服务暂时不可用，请稍后重试'
}
const switchView = (nextView) => { view.value = nextView }
const loadSaved = async () => { const response = await proxy.Request({ url: proxy.Api.zentideInterestSaved, method: 'GET', params: {}, showLoading: false, showError: false }); if (response) { const data = response.data || response; savedIds.value = data.item_ids || []; savedItems.value = data.items || [] } }
const feedback = async (item, action) => { if (action === 'saved' && isSaved(item)) { const response = await proxy.Request({ url: `${proxy.Api.zentideInterestSaved}/${encodeURIComponent(item.item_id)}`, method: 'DELETE', params: {}, showLoading: false }); if (response) { savedIds.value = savedIds.value.filter((id) => id !== item.item_id); savedItems.value = savedItems.value.filter((entry) => entry.item_id !== item.item_id); feedbackState.value = { ...feedbackState.value, [item.item_id]: null } }; return }; feedbackState.value = { ...feedbackState.value, [item.item_id]: action }; const params = { itemId: item.item_id, action }; if (action === 'saved') params.item = item; const response = await proxy.Request({ url: proxy.Api.zentideInterestFeedback, params, dataType: 'json', showLoading: false }); if (response && action === 'saved') { savedIds.value = [...new Set([...savedIds.value, item.item_id])]; savedItems.value = [item, ...savedItems.value.filter((entry) => entry.item_id !== item.item_id)] } }
onMounted(() => { loadKeywords(); loadSaved() })
</script>

