@media(max-width:650px){.insights-page{padding-top:30px}.insights-page:before{height:300px}.hero h1{font-size:39px}.keyword-card{padding:20px;margin-bottom:38px}.result-head{align-items:flex-start}.result-meta{margin-top:16px;justify-content:flex-start}.metric{align-items:flex-start;padding-left:0;padding-right:14px;border-left:0;border-right:1px solid #dce8e3}.metric:last-child{border-right:0}.insight-card{padding:18px}.section-title{align-items:flex-start}}
.target-keywords{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:-1px 0 12px}.target-keywords span{font-size:10px;color:#9aa0b3}.target-keywords b{font-size:10px;font-weight:700;color:#5e5bd5;background:#f0efff;border:1px solid #dfdefb;border-radius:999px;padding:3px 8px}
